function audit<K extends TaskflowEventType>(
  type: K & ActivityAction,
  build: (
    payload: TaskflowEventPayload<K>,
  ) => AuditedInput | Promise<AuditedInput>,
): Unsubscribe {
  return subscribe(type, async (payload) => {
    const envelope: EventEnvelope = payload;
    const input = await build(payload);
    await record(envelope.orgId, type, {
      ...input,
      actorId: envelope.actorId,
      occurredAt: envelope.occurredAt,
