cat > /tmp/actchk/a.test.ts <<EOF
import { it, expect, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("$PWD/tests/server/_support/doubles/misc")).loggerModule);
import { emit } from "@/lib/event-bus";
import { exportActivity, listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "$PWD/tests/server/_support/fixtures";
import { createIssue, assignIssue } from "@/server/services/issue-service";
import { createComment } from "@/server/services/comment-service";

it("works", async () => {
  const cleanup = await useTemporaryDatabase();
  const t = await createTenant("x", "growth");
  const off = registerActivityListeners();
  const base = Date.parse("2026-01-01T00:00:00.000Z");
  for (let i = 0; i < 250; i++) {
    await emit("billing.plan_changed", { orgId: t.org.id, actorId: t.userIds.owner, occurredAt: new Date(base + Math.floor(i/3)*1000).toISOString() as any, from: "free", to: "growth" });
  }
  const json = JSON.parse(await exportActivity(t.actors.admin, { orgId: t.org.id, since: "2026-01-01T00:00:00.000Z" as any, until: "2026-01-01T00:01:23Z" as any, format: "json" }));
  expect(json.length).toBe(250);
  expect(new Set(json.map((e: any) => e.id)).size).toBe(250);
  expect(json[0].metadata).toEqual({ from: "free", to: "growth" });
  const same = JSON.parse(await exportActivity(t.actors.admin, { orgId: t.org.id, since: "2026-01-01T00:00:05.000Z" as any, until: "2026-01-01T00:00:05.000Z" as any, format: "json" }));
  expect(same.length).toBe(3);
  await expect(exportActivity(t.actors.admin, { orgId: t.org.id, since: "2026-01-02T00:00:00.000Z" as any, until: "2026-01-01T00:00:00.000Z" as any, format: "csv" })).rejects.toThrow();
  const issue = await createIssue(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, title: "Hello there", priority: "medium" } as any);
  await assignIssue(t.actors.admin, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.member });
  await createComment(t.actors.admin, { orgId: t.org.id, issueId: issue.id, body: "hi", mentionedUserIds: [] } as any);
  const p = await listActivity(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, limit: 50, cursor: null });
  console.log(p.items.map((e) => [e.action, e.actorId === t.userIds.admin]));
  expect(p.items.map((e) => e.action).sort()).toEqual(["comment.created", "issue.assigned", "issue.created"]);
  off(); cleanup();
});
EOF
